#!/usr/bin/env node
// Database migration runner.
//
// Reads SQL files from ./migrations/ and logs each filename it would apply,
// in order. This is a dry-run: it discovers and orders migrations but does
// not execute any SQL against a database.

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Natural sort comparator so that "2" sorts before "10".
 * Falls back to lexicographic comparison when no numeric prefix is present.
 */
function compareMigrations(a, b) {
  const numA = parseInt(a.match(/^\d+/)?.[0] ?? '', 10);
  const numB = parseInt(b.match(/^\d+/)?.[0] ?? '', 10);

  if (!Number.isNaN(numA) && !Number.isNaN(numB) && numA !== numB) {
    return numA - numB;
  }
  return a.localeCompare(b);
}

function getMigrationFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  return fs
    .readdirSync(dir)
    .filter((file) => file.toLowerCase().endsWith('.sql'))
    .sort(compareMigrations);
}

function run() {
  let files;
  try {
    files = getMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exitCode = 1;
    return;
  }

  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${files.length} migration(s) in ${MIGRATIONS_DIR}:`);
  files.forEach((file, index) => {
    const step = String(index + 1).padStart(2, '0');
    console.log(`  [${step}] would apply: ${file}`);
  });
  console.log('Dry run complete — no SQL was executed.');
}

if (require.main === module) {
  run();
}

module.exports = { getMigrationFiles, compareMigrations };

