const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Minimal .env parser. Returns a key/value map of the file's variables.
 * Does not mutate process.env.
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Env file not found: ${filePath}`);
  }

  const vars = {};
  const lines = fs.readFileSync(filePath, 'utf8').split(/\r?\n/);

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eq = trimmed.indexOf('=');
    if (eq === -1) continue;

    const key = trimmed.slice(0, eq).trim();
    let value = trimmed.slice(eq + 1).trim();
    // Strip surrounding quotes if present.
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }
    vars[key] = value;
  }

  return vars;
}

/**
 * Produce a safe, secret-free description of a connection string for logging.
 * Strips credentials and never returns the raw password or full URL.
 *
 * Example: postgres://admin:hunter2@db.internal:5432/prod
 *      ->  postgres://***@db.internal:5432/prod
 */
function redactConnectionString(connStr) {
  try {
    const url = new URL(connStr);
    const auth = url.username ? '***@' : '';
    const port = url.port ? `:${url.port}` : '';
    return `${url.protocol}//${auth}${url.hostname}${port}${url.pathname}`;
  } catch {
    // If it isn't a parseable URL, don't risk leaking it — return a generic label.
    return '<unparseable connection string (redacted)>';
  }
}

/**
 * Resolve DATABASE_URL from the env file (or process.env as an override).
 * Returns the raw value for use by a real client, but callers should only
 * ever LOG the redacted form.
 */
function resolveDatabaseUrl() {
  const fileVars = parseEnvFile(ENV_FILE);
  const url = process.env.DATABASE_URL || fileVars.DATABASE_URL;
  if (!url) {
    throw new Error('DATABASE_URL not found in environment or .env.test');
  }
  return url;
}

function run() {
  // Resolve and "connect" using the configured DATABASE_URL.
  let dbUrl;
  try {
    dbUrl = resolveDatabaseUrl();
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exitCode = 1;
    return;
  }

  // NOTE: We never log the raw connection string (it contains credentials).
  // Only a redacted form is printed. No real connection is opened.
  console.log(`Connected successfully to ${redactConnectionString(dbUrl)}`);

  let files;

module.exports = {
  getMigrationFiles,
  compareMigrations,
  parseEnvFile,
  redactConnectionString,
  resolveDatabaseUrl,
};

