    .readdirSync(dir)
    .filter((name) => name.toLowerCase().endsWith('.sql'))
    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
}

function main() {
  let migrations;
  try {
    migrations = getMigrations();
  } catch (err) {
    console.error(err.message);
    process.exit(1);
  }

  if (migrations.length === 0) {
    console.log('No migrations found.');
